import React from "react";
import { useNavigate } from "react-router-dom";
import "./HomePage.css";

const HomePage = () => {
  const navigate = useNavigate();

  const handleLearnMore = () => {
    navigate("/about"); // Navigate to the About Us page
  };

  return (
    <div className="home-container">
      <header className="home-header">
        <div className="header-content">
          <h1 className="site-title">Welcome to Our School</h1>
          <p className="site-description">
            Empowering students to achieve excellence through innovation,
            dedication, and community.
          </p>
          <button className="cta-button" onClick={handleLearnMore}>
            Learn More
          </button>
        </div>
      </header>
    </div>
  );
};

export default HomePage;
